/**
 * Renders `public/og.png` from `public/og.svg`, and says when it is stale.
 *
 *   node scripts/build-og-png.mjs          # render it
 *   node scripts/build-og-png.mjs --check  # fail if og.svg has moved since (for CI)
 *
 * ## Why this exists
 *
 * `og.svg` is generated by `build-theme.mjs` and gated by it. `og.png` is the file `og:image` and
 * `twitter:image` actually point at, and until now it was neither — so the two could disagree with
 * nothing to notice. They did: the card said `Every JSX tag is exactly one element.` for a while
 * after that rule was retired, on every link anybody shared.
 *
 * An image cannot be diffed against its source cheaply, so this stamps the hash of the `og.svg` it
 * was rendered from and compares that. Not a substitute for looking at the picture — it answers
 * "was this png made from this svg", which is the question that actually goes wrong.
 *
 * ## Why Chromium
 *
 * The card names its fonts rather than embedding them, so whatever renders it must have real font
 * fallback. `@playwright/test` is already in this repo for the browser tests and its Chromium is
 * already downloaded, so this costs a devDependency and no new binary.
 */
import { createHash } from "node:crypto";
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const svgPath = join(here, "..", "public", "og.svg");
const pngPath = join(here, "..", "public", "og.png");
/** Kept out of `public/`, which is served — this is a build fact, not part of the site. */
const stampPath = join(here, "og.png.stamp");
const check = process.argv.includes("--check");

const svg = readFileSync(svgPath, "utf8");
const stamp = createHash("sha256").update(svg).digest("hex");
const held = existsSync(stampPath) ? readFileSync(stampPath, "utf8").trim() : "";

if (held === stamp && existsSync(pngPath)) {
  if (check) console.log("[og] up to date");
  process.exit(0);
}

if (check) {
  console.error(
    "[og] public/og.png was not rendered from the current public/og.svg\n" +
      "     the card is an image, so nothing else would ever notice.\n" +
      "     run `node scripts/build-og-png.mjs` from apps/docs and commit the result.",
  );
  process.exit(1);
}

const { chromium } = await import("@playwright/test");
const browser = await chromium.launch();
try {
  const page = await browser.newPage({ viewport: { width: 1200, height: 630 }, deviceScaleFactor: 1 });
  await page.setContent(`<!doctype html><style>html,body{margin:0;padding:0}svg{display:block}</style>${svg}`);
  await page.locator("svg").screenshot({ path: pngPath });
} finally {
  await browser.close();
}
writeFileSync(stampPath, `${stamp}\n`);
console.log("[og] public/og.png");
